func resourceAlibabacloudStackPolardbxInstanceRead(d *schema.ResourceData, meta interface{}) error {
	client := meta.(*connectivity.AlibabacloudStackClient)
	polardbxService := PolardbXService{client}
	response, err := polardbxService.DoPolardbxDescribedbinstanceattributeRequest(d.Id())
	// READINS_MAINTAINING
	if err != nil {
		return errmsgs.WrapErrorf(err, errmsgs.DefaultErrorMsg, "alibabacloudstack_polardbx_instance", errmsgs.AlibabacloudStackSdkGoERROR)
	}
	data := response.DBInstance

	d.Set("storage", data.Storage)

	d.Set("cpu_type", data.CpuType)

	d.Set("description", data.Description)

	d.Set("engine_version", data.DBVersion)

	d.Set("cn_node_class", data.CNNodeClass)

	d.Set("cn_node_count", data.CNNodeCount)

	d.Set("create_time", data.CreateTime)

	//	d.Set("db_node_class", data.DBNodeClass)

	//	d.Set("db_node_count", data.DBNodeCount)

	d.Set("dn_node_class", data.DNNodeClass)

	d.Set("dn_node_count", data.DNNodeCount)

	d.Set("network_type", strings.ToLower(data.Network))

	d.Set("connection_string", data.ConnectionString)

	// d.Set("primary_db_instance_id", data.)

	// d.Set("primary_db_instance_id", data.)

	d.Set("status", data.Status)

	d.Set("vswitch_id", data.VSwitchId)

	d.Set("zone_id", data.ZoneId)

	enablePublicConnection := false
	for _, v := range response.DBInstance.ConnAddrs {
		prefix := strings.SplitN(v.ConnectionString, ".", 2)[0]
		if v.Type != "Public" {
			d.Set("private_connection_string_prefix", prefix)
			d.Set("private_connection_string", v.ConnectionString)
			d.Set("private_connection_port", v.Port)
		} else {
			enablePublicConnection = true
			d.Set("public_connection_string_prefix", prefix)
			d.Set("public_connection_string", v.ConnectionString)
			d.Set("public_connection_port", v.Port)
		}
	}
	if !enablePublicConnection {
		d.Set("public_connection_string_prefix", nil)
		d.Set("public_connection_string", nil)
		d.Set("public_connection_port", nil)
	}
	d.Set("enable_public_connection", enablePublicConnection)

	enable_ssl, err := polardbxService.DoPolardbxDescribeDBInstanceSSLRequest(d.Id())
	if err != nil {
		return errmsgs.WrapErrorf(err, errmsgs.DefaultErrorMsg, "alibabacloudstack_polardbx_instance", errmsgs.AlibabacloudStackSdkGoERROR)
	}
	d.Set("enable_ssl", enable_ssl)
	enable_tde, err := polardbxService.DoPolardbxDescribeDBInstanceTDERequest(d.Id())
	if err != nil {
		return errmsgs.WrapErrorf(err, errmsgs.DefaultErrorMsg, "alibabacloudstack_polardbx_instance", errmsgs.AlibabacloudStackSdkGoERROR)
	}
	d.Set("enable_tde", enable_tde)
	if err = polardbxService.RefreshParameters(d, "storage"); err != nil {
		return errmsgs.WrapError(err)
	}
	if err = polardbxService.RefreshParameters(d, "compute"); err != nil {
		return errmsgs.WrapError(err)
	}

	groups, err := polardbxService.DescribePolardbXDBSecurityIPGroup(d.Id())
	if err != nil {
		return errmsgs.WrapError(err)
	}
	if len(groups) > 0 {
		security_groups := make([]map[string]string, 0)
		for _, group := range groups {
			security_group := map[string]string{
				"ips":        group.SecurityIPList,
				"group_name": group.GroupName,
			}
			security_groups = append(security_groups, security_group)
		}
		d.Set("security_groups", security_groups)
	}

	if response, err := client.DoTeaRequest("GET", "polardbx", "2020-02-02", "DescribeDBInstanceTopology", "", nil, map[string]interface{}{"DBInstanceName": d.Id()}, nil); err != nil {
		return err
	} else {
		for _, item := range response["Data"].(map[string]interface{})["LogicInstanceTopology"].(map[string]interface{})["Items"].([]interface{}) {
			data := item.(map[string]interface{})
			if data["CharacterType"].(string) != "polarx_gms" {
				continue
			}
			d.Set("gms_node_class", data["NodeClass"])
			break
		}
	}
	return nil
}

func resourceAlibabacloudStackPolardbxInstanceDelete(d *schema.ResourceData, meta interface{}) error {
	client := meta.(*connectivity.AlibabacloudStackClient)
	// api: polardbx - 2020-02-02 - DeleteDBInstance
	// Check instance status before deletion
	polardbxService := PolardbXService{client}
	stateConf := BuildStateConf([]string{"NodeCreating", "NodeDeleting", "ClassChanging", "Creating", "READINS_MAINTAINING", "SSL_MODIFYING", "NET_MODIFYING", "NET_DELETING", "NET_CREATING", "CONFIG_SWITCHING"}, []string{"Running"}, d.Timeout(schema.TimeoutUpdate), 10*time.Second, polardbxService.PolardbxDescribedbinstanceStateRefreshFunc(d.Id(), []string{"Failed"}))
	if _, err := stateConf.WaitForState(); err != nil {
		if errmsgs.NotFoundError(err) {
			return nil
		}
		return errmsgs.WrapErrorf(err, errmsgs.IdMsg, d.Id())
	}
	time.Sleep(10 * time.Second)
	request := client.NewCommonRequest("POST", "polardbx", "2020-02-02", "DeleteDBInstance", "")

	request.QueryParams["DBInstanceName"] = d.Id()
	wait := incrementalWait(1*time.Second, 5*time.Minute)
	if err := resource.Retry(d.Timeout(schema.TimeoutDelete), func() *resource.RetryError {
		if bresponse, err := client.ProcessCommonRequest(request); err != nil {
			if bresponse == nil {
				return resource.NonRetryableError(errmsgs.WrapErrorf(err, "Process Common Request Failed"))
			}
			raw_data := make(map[string]interface{})
			_ = json.Unmarshal(bresponse.GetHttpContentBytes(), &raw_data)
			code, ok := raw_data["Code"]
			if ok && errmsgs.IsExpectedErrorCodes(code.(string), []string{errmsgs.ThrottlingUser, "DBInstance.InOrder", "UnsupportedReadOrBakReadState"}) {
				wait()
				return resource.RetryableError(err)
			} else {
				errmsg := errmsgs.GetBaseResponseErrorMessage(bresponse.BaseResponse)
				return resource.NonRetryableError(errmsgs.WrapErrorf(err, errmsgs.RequestV1ErrorMsg, "alibabacloudstack_polardbx_instance", request.GetActionName(), errmsgs.AlibabacloudStackSdkGoERROR, errmsg))
			}
		} else {
			return nil
		}
	}); err != nil {
		return err
	}
	return nil
}

